function run(input) {
  const index = new Map();
  for (const item of input.items) {
    for (const tag of item.tags) {
      if (!index.has(tag)) index.set(tag, []);
      index.get(tag).push(item.name);
    }
  }
  return Object.fromEntries(index);
}
